CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_threadwise_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'name', '')); RETURN NEW; END; $$;
CREATE TRIGGER threadwise_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_threadwise_profile();
CREATE TABLE public.workspaces (id uuid PRIMARY KEY, user_id uuid NOT NULL, title text NOT NULL DEFAULT 'My workspace', document jsonb NOT NULL DEFAULT '{"canvases":[]}', revision bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.workspaces TO authenticated;
GRANT ALL ON public.workspaces TO service_role;
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspaces_own ON public.workspaces FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.ai_access_state (user_id uuid PRIMARY KEY, reason text NOT NULL, status integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_access_state TO authenticated;
GRANT ALL ON public.ai_access_state TO service_role;
ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_access_own ON public.ai_access_state FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE FUNCTION public.save_threadwise_workspace(p_id uuid, p_title text, p_document jsonb, p_revision bigint) RETURNS SETOF public.workspaces LANGUAGE plpgsql SET search_path = public SECURITY INVOKER AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF p_revision = -1 THEN RETURN QUERY INSERT INTO public.workspaces(id,user_id,title,document,revision) VALUES(p_id,auth.uid(),p_title,p_document,0) ON CONFLICT DO NOTHING RETURNING *; ELSE RETURN QUERY UPDATE public.workspaces SET title=p_title, document=p_document, revision=revision+1, updated_at=now() WHERE id=p_id AND user_id=auth.uid() AND revision=p_revision RETURNING *; END IF; END; $$;
GRANT EXECUTE ON FUNCTION public.save_threadwise_workspace(uuid,text,jsonb,bigint) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.save_threadwise_workspace(uuid,text,jsonb,bigint) FROM PUBLIC, anon;